// How do I add text to a table cell in a PDF?

// Insert a sentence into the last paragraph of a cell to populate a table in a PDF.

const doc = Api.GetDocument();
const page = doc.GetPage(0);

const table = Api.CreateTable(2, 2);
const cell = table.GetRow(0).GetCell(0);
cell.AddText("Cell content.");

page.AddObject(table);

// How can I determine the type classification of a cell in a PDF?

// Retrieve the object type information for a table cell in a PDF.

const doc = Api.GetDocument();
const page = doc.GetPage(0);

const table = Api.CreateTable(2, 4);
const row = table.GetRow(0);
const cell = row.GetCell(0);
const content = cell.GetContent();
const paragraph = Api.CreateParagraph();
const classType = cell.GetClassType();
paragraph.AddText("Class type: " + classType);
content.Push(paragraph);

page.AddObject(table);

// How do I access what is stored inside a table cell in a PDF?

// Extract the document elements contained within a cell in a PDF.

const doc = Api.GetDocument();
